source='''def transform(grid):
    out = [row[:] for row in grid]
    n = len(grid)
    div_rows = [r for r in range(n) if all(x == 7 for x in grid[r])]
    if div_rows:
        d = div_rows[0]
        bg = grid[0][1]
        for r in range(d):
            for c, x in enumerate(grid[r]):
                if x != bg and x != 7:
                    match = False
                    for rr in range(d + 1, n):
                        if grid[rr][c] != 4:
                            match = grid[rr][c] == x
                            break
                    if not match:
                        out[r][c] = bg
                        out[0][c] = x
                    elif r < d - 1:
                        out[r][c] = bg
                        out[r + 1][c] = x
    else:
        d = next(c for c in range(len(grid[0])) if all(grid[r][c] == 7 for r in range(n)))
        bg = grid[1][0]
        for c in range(d):
            for r in range(n):
                x = grid[r][c]
                if x != bg and x != 7:
                    match = False
                    for cc in range(d + 1, len(grid[0])):
                        if grid[r][cc] != 4:
                            match = grid[r][cc] == x
                            break
                    if not match:
                        out[r][c] = bg
                        out[r][0] = x
                    elif c < d - 1:
                        out[r][c] = bg
                        out[r][c + 1] = x
    return out
'''
